import { test, expect } from '@playwright/test';

// A transient confirmation toast/banner can vanish before this line runs.
// Warn instead of failing the whole test over UI that already did its job --
// a REAL problem still surfaces as the next real step failing for real.
async function softCheck(label: string, fn: () => Promise<void>): Promise<void> {
  try { await fn(); } catch { console.warn('[soft-check] not visible in time (continuing): ' + label); }
}

// --- TEST DATA (edit these values in one place) ---
const data = {
  step3: 'LI-Demo-Domain-' + Date.now(),   // Fill: textbox "A name for your domain" -- unique per run so this is replayable
};

test('add a domain', async ({ page }) => {
  // Step 1: open the application
  await page.goto('https://edc.qa.securiti.xyz/domains');

  // Step 2: Click button "New Domain"   [A testid]
  await page.getByTestId('domains-new-domain-button').click();
  await softCheck('You can always change the description later.', () => expect(page.getByText('You can always change the description later.')).toBeVisible());   // observed on screen right after this step (info)

  // Step 3: Type into textbox "A name for your domain"   [A testid]
  await page.getByTestId('create-domain-name').fill(data.step3);

  // Step 4: Click button "Create"   [A testid]
  await page.getByTestId('create-domain-button').click();
  await softCheck('Created domain!', () => expect(page.getByText('Created domain!')).toBeVisible());   // observed on screen right after this step (success)
});
